'use strict';
(()=>{
const choices=interestFields.filter(g=>g[0]!=='all');
const selected=()=>choices.filter(g=>Array.isArray(prefs.fields)&&prefs.fields.includes(g[0]));
const subjects=(s,g)=>[...new Set(s.achievement.filter(x=>x.grade>1).map(x=>x.subject.replace(/\s*\([\d.]+\)$/,'')))].filter(n=>g[2].test(n));
prefs.fields=selected().map(g=>g[0]);
const fieldButtons=()=>`<div class="field-choice chips" role="group" aria-label="관심 분야 여러 개 선택">${choices.map(g=>`<button type="button" class="chip ${prefs.fields.includes(g[0])?'on':''}" data-field="${g[0]}" aria-pressed="${prefs.fields.includes(g[0])}">${esc(g[1])}</button>`).join('')}</div>`;
const previousSidebar=sidebar;
sidebar=function(){let box=document.createElement('div');box.innerHTML=previousSidebar();let content=box.querySelector('.filter-content');let part=document.createElement('section');part.className='field-settings';part.innerHTML=`<h3>관심 분야 <small>여러 개 선택</small></h3><p class="hint">선택한 분야의 과목을 학교 목록에서 바로 볼 수 있어요. 선택하지 않아도 모든 학교를 둘러볼 수 있습니다.</p>${fieldButtons()}${selected().length?'<button type="button" class="textbtn" data-clearfields>분야 선택 해제</button>':''}`;let divider=content.querySelector('.divider');if(divider)divider.before(part);else content.append(part);let label=box.querySelector('summary small');if(label&&selected().length)label.textContent+=` · 관심 분야 ${selected().length}개`;return box.innerHTML};
const previousCard=card;
card=function(s){let html=previousCard(s),groups=selected();if(!groups.length)return html;let box=document.createElement('div');box.innerHTML=html;let panel=document.createElement('section');panel.className='card-field-subjects';panel.setAttribute('aria-label','관심 분야 관련 과목');panel.innerHTML=groups.map(g=>{let names=subjects(s,g);return `<div class="card-field"><h4>${esc(g[1])} <small>${names.length}개 확인</small></h4>${names.length?`<p>${names.slice(0,4).map(esc).join(' · ')}</p>${names.length>4?`<details><summary>나머지 ${names.length-4}개 과목</summary><p>${names.slice(4).map(esc).join(' · ')}</p></details>`:''}`:'<p class="hint">공시에서 확인된 과목 없음</p>'}</div>`}).join('')+'<small class="field-basis">2026년 수강 내역 기준 · 2027년 개설은 학교 확인</small>';box.querySelector('.school-shortcuts').before(panel);return box.innerHTML};
const previousSchools=schoolsView;
schoolsView=function(){let box=document.createElement('div');box.innerHTML=previousSchools();let status=box.querySelector('.statusline');if(selected().length)status.insertAdjacentHTML('afterend',`<p class="field-list-note"><b>${selected().map(g=>esc(g[1])).join(' · ')}</b> 관련 과목을 표시하고 있어요. 비교할 학교를 2~4곳 선택하면 과목을 나란히 볼 수 있습니다.</p>`);return box.innerHTML};
function comparison(ss){let groups=selected();return `<section class="field-comparison"><h3>관심 분야별 과목 비교</h3><p class="brief">관심 분야는 여러 개 선택할 수 있어요. 휴대전화에서는 표를 좌우로 밀어 학교를 비교하세요.</p>${fieldButtons()}${groups.length?`<p class="field-legend"><span class="common-subject">함께 확인된 과목</span>은 비교 중인 모든 학교에 수강 내역이 있는 과목이에요.</p><div class="field-table-scroll" role="region" aria-label="학교별 관심 분야 과목 비교표" tabindex="0"><table class="field-compare-table"><caption>2026학년도 1학기 공시 · 2·3학년 수강 과목</caption><thead><tr><th scope="col">관심 분야</th>${ss.map(s=>`<th scope="col">${esc(short(s.name))}</th>`).join('')}</tr></thead><tbody>${groups.map(g=>{let lists=ss.map(s=>subjects(s,g)),common=lists[0].filter(n=>lists.every(list=>list.includes(n)));return `<tr><th scope="row">${esc(g[1])}</th>${lists.map(list=>`<td><small>${list.length}개 확인</small><div class="field-subject-tags">${list.map(n=>`<span class="${common.includes(n)?'common-subject':''}">${esc(n)}</span>`).join('')||'<p class="hint">공시에서 확인된 과목 없음</p>'}</div></td>`).join('')}</tr>`}).join('')}</tbody></table></div><p class="hint">과목 수는 학교의 우열을 뜻하지 않아요. 확인된 과목이 없어도 미개설이라고 단정할 수 없습니다. 분야는 앱에서 분류했으며 같은 과목이 여러 분야에 포함될 수 있어요. 2027학년도 선택·개설 여부와 선택 묶음은 각 학교 교육과정에서 확인하세요.</p><div class="field-school-links">${ss.map(s=>`<button class="outline small" data-detail="${s.id}" data-detailtab="curriculum">${esc(short(s.name))} 교육과정 보기</button>`).join('')}</div>`:'<p class="empty">위에서 관심 분야를 선택하면 학교별 관련 과목을 나란히 보여드려요.</p>'}</section>`}
const previousCompare=openCompare;
openCompare=function(){previousCompare();if(prefs.compare.length<2)return;let body=$('#modalContent .modalbody');if(!body)return;let h=$('#modalContent h2');h.textContent='학교 비교';let wrap=document.createElement('div');wrap.className='modalbody field-compare-body';wrap.innerHTML=comparison(prefs.compare.map(school));let rest=document.createElement('details');rest.className='other-school-comparison';rest.innerHTML='<summary>정원·통학·진학 정보도 비교하기</summary>';body.classList.remove('modalbody');rest.append(body);wrap.append(rest);$('#modalContent').append(wrap);};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||(!b.dataset.field&&!b.hasAttribute('data-clearfields')))return;let inCompare=!!b.closest('.field-comparison'),id=b.dataset.field;if(id)prefs.fields=prefs.fields.includes(id)?prefs.fields.filter(x=>x!==id):[...prefs.fields,id];else prefs.fields=[];let focusKey=id?`[data-field="${id}"]`:'[data-field]';let settings=document.querySelector('.compact-sidebar>details');if(settings)settings.open=true;render();if(inCompare){openCompare();$('#modalContent '+focusKey)?.focus({preventScroll:true})}else document.querySelector('.field-settings '+focusKey)?.focus({preventScroll:true});});
if(data){render();renderSim()}
})();
